window.ScripturaLexicons.BDAG_PART_0119 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-emphytos-bdag\" data-source=\"BDAG\" data-search=\"ἔμφυτος, ον émphytos adjetivo implantado; enxertado; inerente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔμφυτος, ον</td><td>adjetivo</td><td>implantado; enxertado; inerente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-en-bdag\" data-source=\"BDAG\" data-search=\"ἐν en preposição com dativo em; entre; com; por; em relação a; durante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐν</td><td>preposição com dativo</td><td>em; entre; com; por; em relação a; durante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enankalizomai-bdag\" data-source=\"BDAG\" data-search=\"ἐναγκαλίζομαι enankalízomai verbo tomar nos braços; abraçar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐναγκαλίζομαι</td><td>verbo</td><td>tomar nos braços; abraçar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enalios-bdag\" data-source=\"BDAG\" data-search=\"ἐνάλιος, ον enálios adjetivo marinho; pertencente ao mar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνάλιος, ον</td><td>adjetivo</td><td>marinho; pertencente ao mar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enallax-bdag\" data-source=\"BDAG\" data-search=\"ἐναλλάξ enalláx advérbio na direção oposta; transversalmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐναλλάξ</td><td>advérbio</td><td>na direção oposta; transversalmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enallomai-bdag\" data-source=\"BDAG\" data-search=\"ἐνάλλομαι enállomai verbo saltar sobre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνάλλομαι</td><td>verbo</td><td>saltar sobre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enanthropeo-bdag\" data-source=\"BDAG\" data-search=\"ἐνανθρωπέω enanthrōpéō verbo assumir forma humana BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνανθρωπέω</td><td>verbo</td><td>assumir forma humana</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enanti-bdag\" data-source=\"BDAG\" data-search=\"ἔναντι énanti advérbio e preposição diante de; em presença de; aos olhos de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔναντι</td><td>advérbio e preposição</td><td>diante de; em presença de; aos olhos de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enantion-bdag\" data-source=\"BDAG\" data-search=\"ἐναντίον enantíon advérbio e preposição diante de; na presença de; por outro lado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐναντίον</td><td>advérbio e preposição</td><td>diante de; na presença de; por outro lado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enantioomai-bdag\" data-source=\"BDAG\" data-search=\"ἐναντιόομαι enantióomai verbo opor-se; contrariar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐναντιόομαι</td><td>verbo</td><td>opor-se; contrariar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enantios-bdag\" data-source=\"BDAG\" data-search=\"ἐναντίος, α, ον enantíos adjetivo oposto; contrário; adversário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐναντίος, α, ον</td><td>adjetivo</td><td>oposto; contrário; adversário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enarges-bdag\" data-source=\"BDAG\" data-search=\"ἐναργής, ές enargḗs adjetivo claro; evidente; visível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐναργής, ές</td><td>adjetivo</td><td>claro; evidente; visível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enaretos-bdag\" data-source=\"BDAG\" data-search=\"ἐνάρετος, ον enáretos adjetivo virtuoso; excelente; excepcional BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνάρετος, ον</td><td>adjetivo</td><td>virtuoso; excelente; excepcional</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enarmonios-bdag\" data-source=\"BDAG\" data-search=\"ἐναρμόνιος, ον enarmónios adjetivo harmonioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐναρμόνιος, ον</td><td>adjetivo</td><td>harmonioso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enarchomai-bdag\" data-source=\"BDAG\" data-search=\"ἐνάρχομαι enárchomai verbo começar; iniciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνάρχομαι</td><td>verbo</td><td>começar; iniciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enatos-bdag\" data-source=\"BDAG\" data-search=\"ἔνατος, η, ον énatos adjetivo numeral ordinal nono BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔνατος, η, ον</td><td>adjetivo numeral ordinal</td><td>nono</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enaphiemi-bdag\" data-source=\"BDAG\" data-search=\"ἐναφίημι enaphíēmi verbo deixar; permitir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐναφίημι</td><td>verbo</td><td>deixar; permitir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eng-bdag\" data-source=\"BDAG\" data-search=\"ἐνγ- eng- remissão ver ἐγγ- BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνγ-</td><td>remissão</td><td>ver ἐγγ-</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-endees-bdag\" data-source=\"BDAG\" data-search=\"ἐνδεής, ές endeḗs adjetivo pobre; carente; insuficientemente instruído BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνδεής, ές</td><td>adjetivo</td><td>pobre; carente; insuficientemente instruído</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-endeigma-bdag\" data-source=\"BDAG\" data-search=\"ἔνδειγμα, ατος, τό éndeigma substantivo neutro prova; evidência; indicação manifesta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔνδειγμα, ατος, τό</td><td>substantivo neutro</td><td>prova; evidência; indicação manifesta</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-emphytos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔμφυτος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦émphytos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">De <span class=\"greek\">ἐμφύω</span>, «implantar»; desde os pré-socráticos, tragédias e Heródoto; inscrições, papiros; Sb 12:10; Ps.-Phoc. 128; Fílon; Josefo, Bell. 1, 88, Ant. 16, 232; Justino Mártir, Ath., R. 63, 19 e outros; A. Burger, Les mots de la famille de <span class=\"greek\">φύω</span> en grec ancien, 1925. Na literatura em geral, ocorre predominantemente com o sentido de «implantado por processo natural, inato» (Heródoto 9, 94, 3: <span class=\"greek\">ἔμφυτον</span> <span class=\"greek\">αὐτίκα</span> <span class=\"greek\">μαντικὴν</span> <span class=\"greek\">εἶχε</span>). Em nossa literatura, somente em extensão figurada do significado, referindo-se a implantação subsequente, mas com conotação de qualidade (em contraste com algo desenvolvido, por exemplo, pelo esforço pessoal: Platão, Eryxias 398c; cf. Píndaro, N. 3, 40s.): <strong>implantado</strong>.</p><p class=\"entry-text\"><span class=\"greek\">λόγος</span> <span class=\"greek\">ἔ</span>., «a palavra do evangelho implantada em vós», Tg 1:21 (como algo implantado, a palavra fica permanentemente estabelecida na pessoa e, à semelhança de qualidades inatas, atua de modo excepcional; ver W. Knox, JTS 46, 1945, pp. 14s.). <span class=\"greek\">ἡ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">δωρεὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">διδαχῆς</span> <span class=\"greek\">αὐτοῦ</span>, «o dom implantado de seu ensinamento», B 9:9. <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">δωρεᾶς</span> <span class=\"greek\">πνευματικῆς</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">εἰλήφατε</span>, «assim, implantado, recebestes o benefício do dom espiritual», B 1:2 (isto é, a beneficência divina é produtiva, conforme atesta o ilustre caráter espiritual dos destinatários, v. 2a; variante textual <span class=\"greek\">οὗ</span> <span class=\"greek\">τό</span>: «cuja bênção implantada, o favor do dom espiritual, recebestes»; ver Windisch, Hdb., ad loc.). — DELG, s.v. <span class=\"greek\">φύομαι</span>; M-M.; TW.</p></section></article>\n<article id=\"entry-en-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦en⟧</span><span class=\"separator\">·</span><span>preposição com dativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong><span class=\"greek\">ἐν</span></strong>, preposição com dativo (Homero em diante). Para a bibliografia, ver o início dos verbetes <span class=\"greek\">ἀνά</span> e <span class=\"greek\">εἰς</span>. Para os empregos especiais no Novo Testamento, ver A. Oepke, TW II, pp. 534–539. Os usos desta preposição são tão numerosos e variados, e frequentemente tão fáceis de confundir, que é impossível tratá-los de modo estritamente sistemático. Basta enumerar as categorias principais, que ajudarão a estabelecer o uso em casos específicos. Os primeiros ouvintes e leitores, não perturbados por debates gramaticais e lexicais, perceberiam prontamente o contexto e encontrariam pouca dificuldade.</p>\n<p class=\"entry-text\"><strong>① Marcador de posição definida pela localização: em, entre</strong> (ideia fundamental, Rob., pp. 586s.).</p>\n<p class=\"entry-text\">ⓐ Do espaço ou lugar <strong>dentro do qual</strong> algo se encontra, «em»: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πόλει</span>, Lc 7:37; <span class=\"greek\">ἐν</span> <span class=\"greek\">Βηθλέεμ</span>, Mt 2:1; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐρήμῳ</span>, 3:1 (Justino, D. 19, 5; cf. A I, 12, 6: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐρημίᾳ</span>); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span>, At 5:42; <span class=\"greek\">ἐν</span> <span class=\"greek\">οἴκῳ</span>, 1Tm 3:15, e muitíssimo frequentemente. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span> <span class=\"greek\">μου</span>, «na casa de meu Pai», Lc 2:49 e talvez Mt 20:15 (cf. Josefo, Ant. 16, 302; C. Ap. 1, 118: <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διός</span>; PTebt 12, 3; POxy 523, 3; Tb 6:11 S; Goodsp., Probs., pp. 81–83). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀγορᾷ</span>, Mt 20:3. <span class=\"greek\">ἐν</span> (<span class=\"greek\">τῷ</span>) <span class=\"greek\">οὐρανῷ</span>, «no céu» (Arato, Phaen. 10; Diodoro Sículo 4, 61, 6; Plutarco, Mor. 359d: <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχὰς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">λάμπειν</span> <span class=\"greek\">ἄστρα</span>; Taciano 12, 2: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄστρα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span>), At 2:19 (Jl 3:3); Ap 12:1; IEph 19:2. — Com citações e relatos do assunto de obras literárias: «em» (Ps.-Demétrio, c. 226: <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Εὐθυδήμῳ</span>; Simplício, em Epict., p. 28, 37: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Φαίδωνι</span>; Amônio Hermeu, em Aristóteles, De Interpret. c. 9, p. 136, 20 Busse: <span class=\"greek\">ἐν</span> <span class=\"greek\">Τιμαίῳ</span> <span class=\"greek\">παρειλήφαμεν</span>, «recebemos como tradição»; 2Mc 2:4; 1Esd 1:40; 5:48; Sir 50:27; Justino, A I, 60, 1: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">Πλάτωνι</span> <span class=\"greek\">Τιμαίῳ</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιστολῇ</span>, 1Co 5:9; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">νόμῳ</span>, Lc 24:44; Jo 1:45; <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">προφήταις</span>, At 13:40; <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἠλίᾳ</span>, «na narrativa de Elias», Rm 11:2 (Justino, D. 120, 3: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰούδα</span>); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ὡσηέ</span>, 9:25 (Justino, D. 44, 2: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰεζεκιήλ</span>); <span class=\"greek\">ἐν</span> <span class=\"greek\">Δαυίδ</span>, «no Saltério» («por Davi» também é provável; ver 6), Hb 4:7; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτέρῳ</span> <span class=\"greek\">προφήτῃ</span>, «em outro profeta», B 6:14. Da vida interior: <span class=\"greek\">φανεροῦσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">συνειδήσεσι</span>, «ser dado a conhecer às (vossas) consciências», 2Co 5:11; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span>, Mt 5:28; 13:19; 2Co 11:12 e outros.</p>\n<p class=\"entry-text\">ⓑ «Sobre»: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὄρει</span> (Xenofonte, An. 4, 3, 31; Diodoro Sículo 14, 16, 2: <span class=\"greek\">λόφος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span>, «colina sobre a qual»; Josefo, Ant. 12, 259; Justino, D. 67, 9: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὄρει</span> <span class=\"greek\">Χωρήβ</span>), Jo 4:20s.; Hb 8:5 (Êx 25:40). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀγορᾷ</span>, «no mercado», Mt 20:3; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span>, «no caminho», Mt 5:25; <span class=\"greek\">ἐν</span> <span class=\"greek\">πλαξίν</span>, «sobre tábuas», 2Co 3:3; <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">γωνίαις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πλατειῶν</span>, «nas esquinas das ruas», Mt 6:5.</p>\n<p class=\"entry-text\">ⓒ «Dentro dos limites de, junto de, perto de» (Sófocles, Fgm. 37 [34 N.²]: <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">λίθῳ</span>, «perto de cada pedra»; Artemidoro 4, 24, p. 217, 19: <span class=\"greek\">ἐν</span> <span class=\"greek\">Τύρῳ</span>, «perto de Tiro»; Polieno 8, 24, 7: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">νησῖδι</span>, «perto da ilha»; Diógenes Laércio 1, 34; 85; 97: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ποσίν</span>, «o que está diante dos próprios pés»; Josefo, Vi. 227: <span class=\"greek\">ἐν</span> <span class=\"greek\">Χαβωλώ</span>); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">γαζοφυλακείῳ</span> (ver verbete), Jo 8:20; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Σιλωάμ</span>, «perto do tanque de Siloé», Lc 13:4; <span class=\"greek\">καθίζειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">δεξιᾷ</span> <span class=\"greek\">τινος</span>, «sentar-se à direita de alguém» (cf. 1Esd 4:29), Ef 1:20; Hb 1:3; 8:1.</p>\n<p class=\"entry-text\">ⓓ «Entre, em» (Homero em diante; PTebt 58, 41 [111 a.C.]; Sir 16:6; 31:9; 1Mc 4:58; 5:2; TestAbr B 9, p. 13, 27 [Stone, p. 74]; Justino, A I, 5, 4: <span class=\"greek\">ἐν</span> <span class=\"greek\">βαρβάροις</span>); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">γενεᾷ</span> <span class=\"greek\">ταύτῃ</span>, «na geração atualmente viva», Mc 8:38; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">γένει</span> <span class=\"greek\">μου</span>, «entre o meu povo», Gl 1:14 (Justino, D. 51, 1 e outros: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">γένει</span> <span class=\"greek\">ὑμῶν</span>); <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span>, Hb 13:26; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὄχλῳ</span>, «na multidão», Mc 5:30 (cf. Sir 7:7); <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀλλήλοις</span>, «mutuamente» (Tucídides 1, 24, 4; Justino, D. 101, 3), Rm 1:12; 15:5; <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἡγεμόσιν</span>, «entre os oficiais comandantes» (Diodoro Sículo 18, 61, 2; Apiano, Bell. Civ. 5, 21 §84), <span class=\"greek\">Ἰούδα</span>, Mt 2:6 e outros; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνθρώποις</span>, «entre as pessoas» (como Himério, Or. 48 [14], 11; Justino, A I, 23, 3; D. 64, 7), Lc 2:14; cf. At 4:12.</p>\n<p class=\"entry-text\">ⓔ «Diante de, na presença de» etc. (cf. Odisseia 2, 194; Eurípides, Andr. 359; Platão, Leg. 9, 879b; Demóstenes 24, 207; Políbio 5, 39, 6; Epicteto 3, 22, 8; Apiano, Maced. 18 §2: <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">φίλοις</span>, «na presença dos amigos dele»; Sir 19:8; Jt 6:2; PPetr. II, 4 [6], 16 [255/254 a.C.]: <span class=\"greek\">δινὸν</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὄχλῳ</span> <span class=\"greek\">ἀτιμάζεσθαι</span>, «diante de uma multidão»); <span class=\"greek\">σοφίαν</span> <span class=\"greek\">λαλοῦμεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τελείοις</span>, «falamos sabedoria na presença de adultos maduros (isto é, espiritualmente desenvolvidos)», 1Co 2:6 (cf. Simplício, em Epict., p. 131, 20: <span class=\"greek\">λέγειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">θεωρήματα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἰδιώταις</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὠσὶν</span> <span class=\"greek\">ὑμῶν</span>, «aos vossos ouvidos», Lc 4:21 (cf. Jz 17:2; 4Rs 23:2; Bar 1:3s.), onde as palavras podem ser ligadas sintaticamente tão bem a <span class=\"greek\">πεπλήρωται</span> quanto a <span class=\"greek\">ἡ</span> <span class=\"greek\">γραφὴ</span> <span class=\"greek\">αὕτη</span> («esta passagem da Escritura lida aos vossos ouvidos»). <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀφθαλμοῖς</span> <span class=\"greek\">τινος</span>, «aos olhos de alguém», isto é, no julgamento dessa pessoa (Sb 3:2; Sir 8:16; Jt 3:4; 12:14; 1Mc 1:12), Mt 21:42 (Sl 117:23). <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> já com o mesmo significado entre os trágicos (Sófocles, Oed. C. 1213: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοί</span>, «no meu julgamento»; Ant. 925: <span class=\"greek\">ἐν</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">καλά</span>; também Platão, Prot. 337b; 343c): <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοί</span>, 1Co 14:11; possivelmente Jo 3:21 (ver 4c abaixo) e Jd 1 também pertencem aqui. — No sentido «forense», <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> pode significar «na jurisdição» ou «no foro de alguém» (Sófocles, Ant. 459; Platão, Gorg. 464d, Leg. 11, 916b; Élio Aristides 38, 3 K. = 7, p. 71 D.; 46, pp. 283, 334 D.; Diodoro Sículo 19, 51, 4; Ps.-Heráclito, Ep. 4, 6; contudo, em várias dessas passagens, o significado pouco ultrapassa «na presença de» [ver acima]); <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span>, 1Co 6:2 («por vós» também é defensável; ver 6 abaixo).</p>\n<p class=\"entry-text\">ⓕ Especialmente na descrição de processos internos: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span>, «consigo mesmo», isto é, «em silêncio»; <span class=\"greek\">διαλογίζεσθαι</span>, Mc 2:8; Lc 12:17; <span class=\"greek\">διαπορεῖν</span>, At 10:17; <span class=\"greek\">εἰδέναι</span>, Jo 6:61; <span class=\"greek\">λέγειν</span>, Mt 3:9; 9:21; Lc 7:49; <span class=\"greek\">εἰπεῖν</span>, 7:39 e outros; <span class=\"greek\">ἐμβριμᾶσθαι</span>, Jo 11:38.</p>\n<p class=\"entry-text\"><strong>② Marcador de estado ou condição: em.</strong></p>\n<p class=\"entry-text\">ⓐ De estar vestido e de metáforas associadas a tal condição: «em, com» (Heródoto 2, 159; Xenofonte, Mem. 3, 11, 4; Diodoro Sículo 1, 12, 9; Herodiano 2, 13, 3; Jt 10:3; 1Mc 6:35; 2Mc 3:33); <span class=\"greek\">ἠμφιεσμένον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μαλακοῖς</span>, «vestido com roupas finas», Mt 11:8; <span class=\"greek\">περιβάλλεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἱματίοις</span>, Ap 3:5; 4:4; <span class=\"greek\">ἔρχεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐνδύμασι</span> <span class=\"greek\">προβάτων</span>, «vir vestido de ovelha», Mt 7:15; <span class=\"greek\">περιπατεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">στολαῖς</span>, «andar com vestes compridas», Mc 12:38 (Taciano 2, 1: <span class=\"greek\">ἐν</span> <span class=\"greek\">πορφυρίδι</span> <span class=\"greek\">περιπατῶν</span>); cf. At 10:30; Mt 11:21; Lc 10:13. <span class=\"greek\">ἐν</span> <span class=\"greek\">λευκοῖς</span>, «de branco» (Artemidoro 2, 3; 4, 2: <span class=\"greek\">ἐν</span> <span class=\"greek\">λευκοῖς</span> <span class=\"greek\">προϊέναι</span>; Epicteto 3, 22, 1), Jo 20:12; Hv 4, 2, 1. Provavelmente corresponde a isso <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span>, «revestido de carne» (cf. Diodoro Sículo 1, 12, 9: divindades aparecem <span class=\"greek\">ἐν</span> <span class=\"greek\">ζῴων</span> <span class=\"greek\">μορφαῖς</span>, «em formas de animais»), 1Tm 3:16; 1Jo 4:2; 2Jo 7. <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">δόξῃ</span> <span class=\"greek\">αὐτοῦ</span>, «em toda a sua glória», Mt 6:29 (cf. 1Mc 10:86). <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δόξῃ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>, «revestido da glória de seu Pai», Mt 16:27; cf. 25:31; Mc 8:38; Lc 9:31.</p>\n<p class=\"entry-text\">ⓑ De outros estados e condições (assim frequentemente com <span class=\"greek\">γίνομαι</span>, <span class=\"greek\">εἰμί</span>; autores áticos; PPetr. II, 11 [1], 8 [século III a.C.]: <span class=\"greek\">γράφε</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">εἰδῶμεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οἷς</span> <span class=\"greek\">εἶ</span>; 39 [g], 16; UPZ 110, 176 [164 a.C.] e outros; LXX; Justino, A I, 13, 2: <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀφθαρσίᾳ</span> <span class=\"greek\">γενέσθαι</span>; 67, 6: <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χρείᾳ</span> <span class=\"greek\">οὖσι</span>; Taciano 20, 1s.: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστι</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἄπειρος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐρανός</span>, … <span class=\"greek\">πεπερασμένος</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τέρματι</span>; Mel., HE 4, 26, 6: <span class=\"greek\">ἐν</span> … <span class=\"greek\">λεηλασίᾳ</span>, «em pilhagem»); <span class=\"greek\">ὑπάρχων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">βασάνοις</span>, Lc 16:23; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θανάτῳ</span>, 1Jo 3:14; <span class=\"greek\">ἐν</span> <span class=\"greek\">ζωῇ</span>, Rm 5:10; <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">δεσμοῖς</span>, Fm 13 (Justino, A II, 2, 11: <span class=\"greek\">ἐν</span> <span class=\"greek\">δ</span>. <span class=\"greek\">γενέσθαι</span>); <span class=\"greek\">ἐν</span> <span class=\"greek\">πειρασμοῖς</span>, 1Pe 1:6; <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλοῖς</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">ἀστοχήμασι</span>, AcPlCor 2:1; <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμοιώματι</span> <span class=\"greek\">σαρκός</span>, Rm 8:3; <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλῷ</span> <span class=\"greek\">ἀγῶνι</span>, 1Ts 2:2; <span class=\"greek\">ἐν</span> <span class=\"greek\">φθορᾷ</span>, «em estado de corruptibilidade», 1Co 15:42; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτοίμῳ</span> <span class=\"greek\">ἔχειν</span>, 2Co 10:6 (cf. PEleph 10, 7 [223/222 a.C.]: <span class=\"greek\">τ</span>. <span class=\"greek\">λοιπῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτοίμῳ</span> <span class=\"greek\">ὄντων</span>; PGen 76, 8; 3Mc 5:8); <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐκστάσει</span>, «em estado de êxtase», At 11:5 (em oposição a Justino, D. 115, 3: <span class=\"greek\">ἐν</span> <span class=\"greek\">καταστάσει</span> <span class=\"greek\">ὤν</span>). De qualidades: <span class=\"greek\">ἐν</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀγάπῃ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἁγιασμῷ</span>, 1Tm 2:15; <span class=\"greek\">ἐν</span> <span class=\"greek\">κακίᾳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φθόνῳ</span>, Tt 3:3; <span class=\"greek\">ἐν</span> <span class=\"greek\">πανουργίᾳ</span>, 2Co 4:2; <span class=\"greek\">ἐν</span> <span class=\"greek\">εὐσεβείᾳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σεμνότητι</span>, 1Tm 2:2; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀνοχῇ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, Rm 3:26; <span class=\"greek\">ἐν</span> <span class=\"greek\">μυστηρίῳ</span>, 1Co 2:7; <span class=\"greek\">ἐν</span> <span class=\"greek\">δόξῃ</span>, Fp 4:19.</p>\n<p class=\"entry-text\"><strong>③ Marcador de extensão em direção a um objetivo entendido como situado dentro de uma área ou condição: para dentro de.</strong> <span class=\"greek\">ἐν</span> é ocasionalmente usado com verbos de movimento, nos quais normalmente se esperaria <span class=\"greek\">εἰς</span> (Diodoro Sículo 23, 8, 1: <span class=\"greek\">Ἄννων</span> <span class=\"greek\">ἐπέρασε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Σικελίᾳ</span>; Hero I, 142, 7; 182, 4; Pausânias 7, 4, 3: <span class=\"greek\">διαβάντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Σάμῳ</span>; Epicteto 1, 11, 32; 2, 20, 33; Eliano, VH 4, 18; Vettius Valens 210, 26; 212, 6 e outros, ver índice; Pel.-Leg. 1, 4; 5; 2, 1; PParis 10, 2 [145 a.C.]: <span class=\"greek\">ἀνακεχώρηκεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἀλεξανδρείᾳ</span>; POxy 294, 4; BGU 22, 13; Tb 5:5 BA; 1Mc 10:43; TestAbr B 2, p. 106, 23 = Stone, p. 60 [ver Thackeray, p. 25, sobre a LXX]; <span class=\"greek\">πέμψον</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πολέμῳ</span>, En 10:9; TestAbr A 6, p. 83, 22 [Stone, p. 14]: <span class=\"greek\">δάκρυα</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">νιπτῆρι</span> <span class=\"greek\">πίπτοντα</span>): <span class=\"greek\">εἰσέρχεσθαι</span>, Lc 9:46; Ap 11:11; <span class=\"greek\">ἀπάγειν</span>, GJs 6:1; <span class=\"greek\">ἀνάγειν</span>, 7:1; <span class=\"greek\">εἰσάγειν</span>, 10:1; <span class=\"greek\">καταβαίνειν</span>, Jo 5:3 (4), variante textual; <span class=\"greek\">ἀναβαίνειν</span>, GJs 22:13; <span class=\"greek\">ἀπέρχεσθαι</span> (Diodoro Sículo 23, 18, 5), Hs 1:6; <span class=\"greek\">ἥκειν</span>, GJs 5:1; <span class=\"greek\">ἀποστέλλειν</span>, 25:1. Deve-se entender de outro modo <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Ἰουδαίᾳ</span>, «a palavra saiu», isto é, «espalhou-se por toda a Judeia», Lc 7:17; semelhantemente 1Ts 1:8. A expressão metafórica <span class=\"greek\">ἐπιστρέψαι</span> <span class=\"greek\">ἀπειθεῖς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φρονήσει</span> <span class=\"greek\">δικαίων</span>, «converter os desobedientes à sabedoria dos justos», Lc 1:17, é notável, mas compatível com o sentido fundamental de <span class=\"greek\">ἐν</span>. Ver ainda <span class=\"greek\">γίνομαι</span>, <span class=\"greek\">δίδωμι</span>, <span class=\"greek\">ἵστημι</span>, <span class=\"greek\">καλέω</span> e <span class=\"greek\">τίθημι</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span>, «entre», por vezes responde à pergunta «para onde?» (B-D-F §215, 3), Mt 10:16; Lc 10:3; 8:7.</p>\n<p class=\"entry-text\"><strong>④ Marcador de associação estreita dentro de um limite: em.</strong></p>\n<p class=\"entry-text\">ⓐ Figuradamente, quanto a pessoas, para indicar o estado de estar cheio de alguma coisa ou dominado por ela: «em alguém», isto é, «no seu íntimo». <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">κατοικεῖ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλήρωμα</span>, «nele habita toda a plenitude», Cl 2:9. <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ἐκτίσθη</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> (provavelmente deve ser compreendido em sentido locativo, não instrumental, pois, de outro modo, <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐ</span>. seria idêntico a <span class=\"greek\">δι</span>’ <span class=\"greek\">αὐ</span>. no mesmo versículo), «tudo foi criado em associação com ele», 1:16 (cf. Marco Aurélio, 4, 23: <span class=\"greek\">ἐν</span> <span class=\"greek\">σοὶ</span> <span class=\"greek\">πάντα</span>; Herm. Wr. 5, 10; A. Feuillet, NTS 12, 1965, pp. 1–9). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">κέκρυπται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ζωὴ</span> <span class=\"greek\">ὑμῶν</span>, «vossa vida está escondida em Deus», 3:3; cf. 2:3. Quanto ao pecado nos seres humanos, Rm 7:17s.; cf. <span class=\"greek\">κατεργάζεσθαι</span>, v. 8. Quanto a Cristo, que, como ser espiritual, preenche as pessoas de modo a dirigir-lhes a vida, Rm 8:10; 2Co 13:5; permanece nelas, Jo 6:56; vive nelas, Gl 2:20; e nelas toma forma, 4:19. Quanto à palavra divina: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span>, 1Jo 1:10; <span class=\"greek\">μένειν</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, Jo 5:38; <span class=\"greek\">ἐνοικεῖν</span>, Cl 3:16. Quanto ao Espírito de Deus: <span class=\"greek\">οἰκεῖν</span> (<span class=\"greek\">ἐνοικεῖν</span>) <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, Rm 8:9, 11; 1Co 3:16; 2Tm 1:14. Quanto aos dons espirituais, 1Tm 4:14; 2Tm 1:6. Quanto aos poderes milagrosos: <span class=\"greek\">ἐνεργεῖν</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «estar em atividade em alguém», Mt 14:2; Mc 6:14; <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> <span class=\"greek\">εὐάρεστον</span>, Hb 13:21. A mesma expressão acerca de Deus ou de espíritos maus, que de alguma maneira atuam nas pessoas: 1Co 12:6; Fp 2:13; Ef 2:2 e outros.</p>\n<p class=\"entry-text\">ⓑ Do todo ao qual as partes estão estreitamente unidas: <span class=\"greek\">μένειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀμπέλῳ</span>, «permanecer na videira», Jo 15:4; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">σώματι</span> <span class=\"greek\">μέλη</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἔχομεν</span>, «em um só corpo temos muitos membros», Rm 12:4; <span class=\"greek\">κρέμασθαι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «depender de alguma coisa», Mt 22:40.</p>\n<p class=\"entry-text\">ⓒ Especialmente no uso paulino ou joanino, para designar relação pessoal estreita, na qual o referente da expressão com <span class=\"greek\">ἐν</span> é considerado a influência determinante: «sob o domínio de, sob a influência de, em íntima associação com» (cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Δαυιδ</span> <span class=\"greek\">εἰμί</span>, 2Rs 19:44). Quanto a Cristo: <span class=\"greek\">εἶναι</span>, <span class=\"greek\">μένειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρί</span> (<span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>), Jo 10:38; 14:10s. (diferentemente, C. Gordon, «‘In’ of Predication or Equivalence», JBL 100, 1981, pp. 612s.); e quanto aos cristãos, 1Jo 3:24; 4:13, 15s.; «estar ou permanecer em Cristo», Jo 14:20; 15:4s.; <span class=\"greek\">μένειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">υἱῷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρί</span>, 1Jo 2:24. <span class=\"greek\">ἔργα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">εἰργασμένα</span>, «obras feitas em comunhão com Deus», Jo 3:21 (mas ver 1e acima). — Em Paulo, a relação do indivíduo com Cristo é muito frequentemente expressa por fórmulas como <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> etc., e também vice-versa (F. Neugebauer, NTS 4, 1957/58, pp. 124–138; A. Wedderburn, JSNT 25, 1985, pp. 83–97): <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">Χριστός</span>, Gl 2:20, aqui, porém, no sentido de a acima.</p>\n<p class=\"entry-text\">Ver, por exemplo, Dssm., D. ntl. Formel «in Christo Jesu», 1892; E. Weber, D. Formel «in Chr. Jesu» u. d. paul. Christusmystik, NKZ 31, 1920, pp. 213ss.; L. Brun, Zur Formel «in Chr. Jesus» im Phil, Symbolae Arctoae 1, 1922, pp. 19–37; M. Hansen, Omkring Paulus-Formeln «i Kristus», TK 4/10, 1929, pp. 135–159; H. Böhlig, «<span class=\"greek\">Ἐν</span> <span class=\"greek\">κυρίῳ</span>», G. Heinrici Festschr., 1914, pp. 170–175; O. Schmitz, D. Christusgemeinschaft d. Pls², 1956; A. Wikenhauser, D. Christusmystik d. Pls², 1956; K. Mittring, Heilswirklichkeit b. Pls; Beitrag z. Verständnis der unio cum Christo in d. Plsbriefen, 1929; A. Schweitzer, D. Mystik d. Ap. Pls, 1930 (tradução inglesa por W. Montgomery, The Myst. of Paul the Ap., 1931); W. Schmauch, In Christus, 1935; B. Easton, Pastoral Ep., 1947, pp. 210s.; F. Büchsel, «In Chr.» b. Pls, ZNW 42, 1949, pp. 141–158. Também H. Korn, D. Nachwirkungen d. Christusmystik d. Pls in den Apost. Vätern, dissertação, Berlim, 1928; E. Andrews, Interpretation 6, 1952, pp. 162–177; H.-L. Parisius, ZNW 49, 1958, pp. 285–288 (dez passagens «forenses»); J. Allan, NTS 5, 1958/59, pp. 54–62 (Efésios), ibid. 10, 1963, pp. 115–121 (Pastorais); F. Neugebauer, In Christus etc., 1961; M. Dahl, The Resurrection of the Body (1Co 15), 1962, pp. 110–113.</p>\n<p class=\"entry-text\">Paulo dispõe das mais variadas expressões para esse novo princípio de vida: «vida em Cristo», Rm 6:11, 23; «amor em Cristo», 8:39; «graça dada em Cristo», 1Co 1:4; «liberdade em Cristo», Gl 2:4; «bênção em Cristo», 3:14; «unidade em Cristo», v. 28. <span class=\"greek\">στήκειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, «permanecer firme no Senhor», Fp 4:1; <span class=\"greek\">εὑρεθῆναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χ</span>., «ser encontrado em Cristo», 3:9; <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χ</span>., 1Co 1:30; <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χ</span>., Rm 8:1; 1Pe 5:14; <span class=\"greek\">κοιμᾶσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χ</span>., «adormecer em Cristo», 1Co 15:18; <span class=\"greek\">ἀποθνῄσκειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, «morrer no Senhor», Ap 14:13; <span class=\"greek\">ζῳοποιεῖσθαι</span>, «ser vivificado», 1Co 15:22. A fórmula é especialmente comum com verbos que denotam convicção, esperança etc.: <span class=\"greek\">πεποιθέναι</span>, Gl 5:10; Fp 1:14; 2Ts 3:4; <span class=\"greek\">παρρησίαν</span> <span class=\"greek\">ἔχειν</span>, Fm 8; <span class=\"greek\">πέπεισμαι</span>, Rm 14:14; <span class=\"greek\">ἐλπίζειν</span>, Fp 2:19; <span class=\"greek\">καύχησιν</span> <span class=\"greek\">ἔχειν</span>, Rm 15:17; 1Co 15:31; <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">φρονεῖν</span>, Fp 4:2; <span class=\"greek\">ὑπακούειν</span>, Ef 6:1; <span class=\"greek\">λαλεῖν</span>, 2Co 2:17; 12:19; <span class=\"greek\">ἀλήθειαν</span> <span class=\"greek\">λέγειν</span>, Rm 9:1; <span class=\"greek\">λέγειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μαρτύρεσθαι</span>, Ef 4:17.</p>\n<p class=\"entry-text\">Mas também, independentemente desses verbos, em numerosas passagens ela é utilizada com substantivos e verbos dos mais variados tipos, muitas vezes sem ênfase especial, para indicar o âmbito no qual alguma coisa acontece ou aconteceu, ou para designá-la como estreitamente associada a Cristo; pode ser traduzida de diversos modos: «em conexão com», «em íntima associação com», «tendo em mente»: <span class=\"greek\">ἁγιάζεσθαι</span>, 1Co 1:2; ou <span class=\"greek\">ἅγιος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χ</span>., Fp 1:1; <span class=\"greek\">ἀσπάζεσθαί</span> <span class=\"greek\">τινα</span>, 1Co 16:19; <span class=\"greek\">δικαιοῦσθαι</span>, Gl 2:17; <span class=\"greek\">κοπιᾶν</span>, Rm 16:12; <span class=\"greek\">παρακαλεῖν</span>, 1Ts 4:1; <span class=\"greek\">προσδέχεσθαί</span> <span class=\"greek\">τινα</span>, Rm 16:2; Fp 2:29; <span class=\"greek\">χαίρειν</span>, 3:1; 4:4, 10; <span class=\"greek\">γαμηθῆναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, «casar-se no Senhor», isto é, «casar-se com um cristão», 1Co 7:39; <span class=\"greek\">προϊστάμενοι</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, «vossos dirigentes cristãos (na igreja)», 1Ts 5:12 (mas ver <span class=\"greek\">προί̈</span><span class=\"greek\">στημι</span> 1 e 2); <span class=\"greek\">εὐάρεστος</span>, Cl 3:20; <span class=\"greek\">νήπιος</span>, 1Co 3:1; <span class=\"greek\">φρόνιμος</span>, 4:10; <span class=\"greek\">παιδαγωγοί</span>, v. 15; <span class=\"greek\">ὁδοί</span>, v. 17. Por isso, é utilizada em perífrases que significam «cristão»: <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, Rm 16:11; <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χ</span>., 2Co 12:2; <span class=\"greek\">αἱ</span> <span class=\"greek\">ἐκκλησίαι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χ</span>., Gl 1:22; 1Ts 2:14; <span class=\"greek\">νεκροὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χ</span>., 4:16; <span class=\"greek\">ἐκλεκτός</span>, Rm 16:13; <span class=\"greek\">δόκιμος</span>, v. 10; <span class=\"greek\">δέσμιος</span>, Ef 4:1; <span class=\"greek\">πιστὸς</span> <span class=\"greek\">διάκονος</span>, 6:21; <span class=\"greek\">ἐν</span> <span class=\"greek\">Χ</span>. <span class=\"greek\">γεννᾶν</span> <span class=\"greek\">τινα</span>, «tornar-se pai ou mãe de alguém na vida cristã», 1Co 4:15; <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">μου</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">ἐστε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, «vós sois a minha obra no Senhor», 9:1.</p>\n<p class=\"entry-text\">O emprego de <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> como expressão formular é semelhante: <span class=\"greek\">ἐν</span> <span class=\"greek\">πν</span>. <span class=\"greek\">εἶναι</span>, «estar sob o impulso do espírito», isto é, «do novo eu», em oposição a <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span>, «sob o domínio do velho eu», Rm 8:9; cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">νόμῳ</span>, 2:12. <span class=\"greek\">λαλεῖν</span>, «falar sob inspiração divina», 1Co 12:3. <span class=\"greek\">ἐγενόμην</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span>, «fui tomado por inspiração», Ap 1:10; 4:2; em oposição a <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">γενόμενος</span>, «voltou a si», At 12:11 (cf. Xenofonte, An. 1, 5, 17 e outros). — <span class=\"greek\">ἐν</span> <span class=\"greek\">πν</span>. <span class=\"greek\">εἶναι</span> também expressa a ideia de que alguém se encontra sob a influência especial de um espírito bom ou mesmo indesejável: Mt 22:43; Mc 12:36; Lc 2:27; 1Co 12:3; Ap 17:3; 21:10. <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πν</span>. <span class=\"greek\">ἀκαθάρτῳ</span> (<span class=\"greek\">ὤν</span>), Mc 1:23 (ver G. Björck, ConNeot 7, 1942, pp. 1–3). — <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πονηρῷ</span> <span class=\"greek\">κεῖσθαι</span>, «estar sob o poder do maligno», 1Jo 5:19. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">νόμῳ</span>, «os que estão sujeitos à lei», Rm 3:19. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἀδὰμ</span> <span class=\"greek\">ἀποθνῄσκειν</span>, «morrer em razão da ligação com Adão», 1Co 15:22. — Sobre a fórmula <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀνόματι</span> (<span class=\"greek\">Χριστοῦ</span>), ver <span class=\"greek\">ὄνομα</span> 1, especialmente d<span class=\"greek\">γ</span>ג. O Antigo Testamento é a fonte da expressão <span class=\"greek\">ὀμνύναι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «jurar por alguém ou alguma coisa» (frequente na LXX), Mt 5:34ss.; 23:16, 18ss.; Ap 10:6; <span class=\"greek\">παραγγέλλομέν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἰησοῦ</span>, At 19:14, variante textual. O emprego em <span class=\"greek\">ὁμολογεῖν</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «reconhecer alguém», Mt 10:32; Lc 12:8 (ver <span class=\"greek\">ὁμολογέω</span> 4b), é aramaico.</p>\n<p class=\"entry-text\"><strong>⑤ Marcador que introduz meio ou instrumento: com.</strong> Construção iniciada já em Homero (muitos exemplos do <span class=\"greek\">ἐν</span> instrumental na edição de Radermacher de Ps.-Demétrio, Eloc., p. 100; Reader, Polemo, p. 258), mas cuja ampla difusão em nossa literatura se deve em parte à influência da LXX e à semelhança com a construção hebraica com בְּ (B-D-F §219; Mlt., p. 104; Mlt-H., pp. 463s.; ver especialmente M-M., p. 210).</p>\n<p class=\"entry-text\">ⓐ Pode introduzir pessoas ou coisas que acompanham alguém para assegurar um objetivo: <strong>«junto com»</strong>.</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. Com pessoas, especialmente força militar, com fusão das ideias associativa (ver 4) e instrumental (1Mc 1:17; 7:14, 28 e outros): <span class=\"greek\">ἐν</span> <span class=\"greek\">δέκα</span> <span class=\"greek\">χιλιάσιν</span> <span class=\"greek\">ὑπαντῆσαι</span>, «ir ao encontro com dez mil homens», Lc 14:31 (cf. 1Mc 4:6, 29: <span class=\"greek\">συνήντησεν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">Ἰούδας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δέκα</span> <span class=\"greek\">χιλιάσιν</span> <span class=\"greek\">ἀνδρῶν</span>); <span class=\"greek\">ἦλθεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μυριάσιν</span> <span class=\"greek\">αὐτοῦ</span>, Jd 14 (cf. Jt 16:3: <span class=\"greek\">ἦλθεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μυριάσι</span> <span class=\"greek\">δυνάμεως</span> <span class=\"greek\">αὐτοῦ</span>).</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Com coisas (frequentemente na LXX; PTebt 41, 5 [cerca de 119 a.C.]; 16, 14 [114 a.C.]; 45, 17 e outros, onde pessoas irrompem na aldeia ou na casa <span class=\"greek\">ἐν</span> <span class=\"greek\">μαχαίρῃ</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅπλοις</span>, «com espada, com armas»; Justino, D. 86, 6: <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀξίνης</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ἧ</span> <span class=\"greek\">πεπορευμένοι</span> <span class=\"greek\">ἦσαν</span> … <span class=\"greek\">κόψαι</span> <span class=\"greek\">ξύλα</span>): <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥάβδῳ</span> <span class=\"greek\">ἔρχεσθαι</span>, «vir com uma vara (como instrumento de disciplina)», 1Co 4:21 (cf. Luciano, Dial. Mort. 23, 3: <span class=\"greek\">Ἑρμῆν</span> <span class=\"greek\">καθικόμενον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ῥάβδῳ</span>; Gn 32:11; 1Rs 17:43; 1Cr 11:23; Dssm., B, pp. 115s. [BS, p. 120]). <span class=\"greek\">ἐν</span> <span class=\"greek\">πληρώματι</span> <span class=\"greek\">εὐλογίας</span>, «com a plenitude da bênção», Rm 15:29; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">βασιλείᾳ</span> <span class=\"greek\">αὐτοῦ</span>, Mt 16:28; <span class=\"greek\">ἐν</span> <span class=\"greek\">αἵματι</span>, Hb 9:25 (cf. Mq 6:6); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὕδατι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αἵματι</span>, 1Jo 5:6; <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δυνάμει</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἠλίου</span>, «munido do espírito e poder de Elias», Lc 1:17; <span class=\"greek\">φθάνειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">εὐαγγελίῳ</span>, «chegar com a pregação do evangelho», 2Co 10:14; <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ζύμῃ</span> <span class=\"greek\">παλαιᾷ</span>, «não sobrecarregados com fermento velho», 1Co 5:8.</p>\n<p class=\"entry-text\">ⓑ Pode expressar meio ou instrumentalidade em termos de localização para determinada ação (cf. TestAbr A 12, p. 91, 5s. [Stone, p. 30]: <span class=\"greek\">κρατῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χειρὶ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ζυγόν</span>; Taciano 9, 2: <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πεσσοῖς</span> <span class=\"greek\">ἀθύροντες</span>, «os que jogam com peças de jogo» [como, por exemplo, no gamão]): <span class=\"greek\">κατακαίειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πυρί</span>, «queimar com fogo», Ap 17:16 (cf. Bar 1:2; 1Esd 1:52; 1Mc 5:5 e outros; já em Ilíada 24, 38; cf. POxy 2747, 74; Eliano, HA 14, 15; além disso, o <span class=\"greek\">ἐν</span> de Ap 17:16 não é textualmente seguro). <span class=\"greek\">ἐν</span> <span class=\"greek\">ἅλατι</span> <span class=\"greek\">ἁλίζειν</span>, <span class=\"greek\">ἀρτύειν</span>, «salgar, temperar com sal», Mt 5:13; Mc 9:50; Lc 14:34 (ver M-M., p. 210; W. Hutton, ET 58, 1946/47, pp. 166–168). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αἵματι</span> <span class=\"greek\">λευκαίνειν</span>, «branquear com o sangue», Ap 7:14; <span class=\"greek\">ἐν</span> <span class=\"greek\">αἵματι</span> <span class=\"greek\">καθαρίζειν</span>, «purificar com sangue», Hb 9:22; <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥομφαίᾳ</span> <span class=\"greek\">ἀποκτείνειν</span>, «matar com a espada», Ap 6:8 (1Esd 1:50; 1Mc 2:9; cf. 3:3; Jt 16:4; <span class=\"greek\">ἀπολεῖ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥομφαίᾳ</span>, En 99:16; 4 [6] Esd [POxy 1010]: <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥ</span>. <span class=\"greek\">πεσῇ</span> … <span class=\"greek\">πεσοῦνται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μαχαίρῃ</span>; cf. Luciano, Hist. Conscrib. 12: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀκοντίῳ</span> <span class=\"greek\">φονεύειν</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">μαχαίρῃ</span> <span class=\"greek\">πατάσσειν</span>, «ferir com espada», Lc 22:49 (<span class=\"greek\">διχοτομήσατε</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>., GrBar 16:3); <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπόλλυσθαι</span>, «perecer pela espada», Mt 26:52; <span class=\"greek\">ποιμαίνειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥάβδῳ</span> <span class=\"greek\">σιδηρᾷ</span>, «apascentar com vara de ferro», Ap 2:27; 12:5; 19:15 (ver <span class=\"greek\">ποιμαίνω</span> 2a<span class=\"greek\">γ</span> e cf. PGM 36, 109). <span class=\"greek\">καταπατεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ποσίν</span>, «pisar alguma coisa com os pés», Mt 7:6 (cf. Sir 38:29). <span class=\"greek\">δύο</span> <span class=\"greek\">λαοὺς</span> <span class=\"greek\">βλέπω</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὀφθαλμοῖς</span> <span class=\"greek\">μου</span>, «vejo dois povos com meus olhos», GJs 17:2 (<span class=\"greek\">ἐν</span> <span class=\"greek\">ὀφθαλμοῖσιν</span> <span class=\"greek\">ὀρᾶν</span>, «ver com os olhos»: cf. Ilíada 1, 587; Odisseia 8, 459; Calino [século VII a.C.], Fgm. 1, 20 Diehl²). <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">κράτος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">βραχίονι</span>, «realizar um feito poderoso com o braço», Lc 1:51 (cf. Sir 38:30); cf. Lc 11:20. <span class=\"greek\">δικαιοῦσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αἵματι</span>, «ser justificado pelo sangue», Rm 5:9; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁγιασμῷ</span> <span class=\"greek\">πνεύματος</span>, 2Ts 2:13; 1Pe 1:2; <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">παρακλήσει</span>, 2Co 7:7; <span class=\"greek\">εὐλογεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">εὐλογίᾳ</span>, Ef 1:3; <span class=\"greek\">λαλοῦντες</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ψάλμοις</span>, Ef 5:19; <span class=\"greek\">ἀσπάσασθαι</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">εὐχῇ</span>, «saudar com oração», GJs 24:1. Quanto ao processo intelectual: <span class=\"greek\">γινώσκειν</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «saber ou reconhecer por meio de alguma coisa» (cf. Tucídides 7, 11, 1: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐπιστολαῖς</span> <span class=\"greek\">ἴστε</span>; Sir 4:24; 11:28; 26:29), Jo 13:35; 1Jo 3:19; cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κλάσει</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἄρτου</span>, «no partir do pão», Lc 24:35 (ver 10c). — O <span class=\"greek\">ἐν</span> que substitui o genitivo de preço também é instrumental: <span class=\"greek\">ἠγόρασας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αἵματί</span> <span class=\"greek\">σου</span>, «compraste com teu sangue», Ap 5:9 (cf. 1Cr 21:24: <span class=\"greek\">ἀγοράζω</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀργυρίῳ</span>). — <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span>, «pelo qual», Rm 14:21. — O idioma <span class=\"greek\">ἀλλάσσειν</span>, <span class=\"greek\">μεταλλάσσειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «trocar algo por outra coisa», Rm 1:23, 25 (cf. Sl 105:20), não é estranho ao grego (Sófocles, Ant. 945: Dânae teve de <span class=\"greek\">οὐράνιον</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἀλλάξαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χαλκοδέτοις</span> <span class=\"greek\">αὐλαῖς</span>, «trocar a luz celeste por câmaras revestidas de bronze»).</p>\n<p class=\"entry-text\"><strong>⑥ Marcador de agência: com a ajuda de</strong> (Diodoro Sículo 19, 46, 4: <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">μετέχουσι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">συνεδρίου</span>, «com a ajuda dos membros do conselho»; Filóstrato, Vi. Apoll. 7, 9, p. 259, 31: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐκείνῳ</span> <span class=\"greek\">ἑαλωκότες</span>): <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἄρχοντι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δαιμονίων</span> <span class=\"greek\">ἐκβάλλει</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δαιμόνια</span>, «ele expulsa demônios com a ajuda do príncipe dos demônios», Mt 9:34; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτερογλώσσοις</span> <span class=\"greek\">λαλεῖν</span>, «falar com outras línguas», 1Co 14:21; <span class=\"greek\">κρίνειν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκουμένην</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνδρί</span>, «julgar o mundo por meio de um homem», At 17:31 (cf. SIG² 850, 8 [173/172 a.C.]: <span class=\"greek\">κριθέντω</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἄνδροις</span> <span class=\"greek\">τρίοις</span>; Sinésio, Ep. 91, p. 231b: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνδρί</span>); talvez 1Co 6:2 (ver 1e); <span class=\"greek\">ἀπολύτρωσις</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χρ</span>., «redenção por meio de Cristo», Rm 3:24 (cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">σωθήσεσθε</span>, Justino, A I, 60, 3).</p>\n<p class=\"entry-text\"><strong>⑦ Marcador da circunstância ou condição sob a qual algo ocorre.</strong> <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">κρίνεις</span>, Rm 2:1 (mas ver B-D-F §219, 2); <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">δοκιμάζει</span>, 14:22; <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">καυχῶνται</span>, 2Co 11:12; <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">τις</span> <span class=\"greek\">τολμᾷ</span>, 11:21; <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">καταλαλοῦσιν</span>, «enquanto difamam», 1Pe 2:12; cf. 3:16 (sobre essas passagens petrinas, ver também <span class=\"greek\">ὅς</span> 1k); <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ξενίζονται</span>, «em vista da vossa atitude mudada, acham estranho», 4:4. Em 1Pe 3:19, <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> pode referir-se semelhantemente a uma circunstância alterada, isto é, da morte para a vida (W. Dalton, Christ’s Proclamation to the Spirits, 1965, especialmente pp. 135–142: «nesta esfera, sob esta influência» [do espírito]). Outras possibilidades: «no que diz respeito a isto»: <span class=\"greek\">πνεῦμα</span>· <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span>, «espírito; no qual» (F. Zimmermann, APF 11, 1935, p. 174: «enquanto isso» [indessen]; B. Reicke, The Disobedient Spirits and Christian Baptism, 1946, pp. 108–115: «naquela ocasião», isto é, quando ele morreu).</p><p class=\"entry-text\">Antes de infinitivo substantivado (frequentemente na LXX; ver K. Huber, Unters. über den Sprachchar. des griech. Lev., dissertação, Zurique, 1916, p. 83): «no fato de», com infinitivo presente (POxy 743, 35 [2 a.C.]: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">δέ</span> <span class=\"greek\">με</span> <span class=\"greek\">περισπᾶσθαι</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἠδυνάσθην</span> <span class=\"greek\">συντυχεῖν</span> <span class=\"greek\">Ἀπολλωνίῳ</span>; Justino, D. 10, 3: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μήτε</span> <span class=\"greek\">σάββατα</span> <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">μήτε</span> …): <span class=\"greek\">βασανιζομένους</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐλαύνειν</span>, «afligidos enquanto avançavam com dificuldade nas ondas», isto é, «tendo dificuldade para progredir», Mc 6:48; <span class=\"greek\">ἐθαύμαζον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">χρονίζειν</span> … <span class=\"greek\">αὐτόν</span>, «admiravam-se por causa da demora dele», Lc 1:21; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span> <span class=\"greek\">ἐκτείνειν</span> <span class=\"greek\">σε</span>, «no fato de estenderes tua mão», At 4:30; cf. 3:26; Hb 8:13. Com infinitivo aoristo: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὑποτάξαι</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span>, Hb 2:8. Às vezes, os usos circunstancial e temporal (ver 7 e 10) misturam-se de tal modo que é difícil distingui-los; assim, em algumas passagens citadas acima e também Hv 1, 1, 8 e outras (B-D-F §404, 3; Rob., p. 1073). — W. Hutton, «Considerations for the Translation of <span class=\"greek\">ἐν</span>», Bible Translator 9, 1958, pp. 163–170; resposta de N. Turner, ibid. 10, 1959, pp. 113–120. — Sobre <span class=\"greek\">ἐν</span> com artigo e infinitivo, ver I. Soisalon-Soininen, Die Infinitive in der LXX, 1965, pp. 80ss.</p>\n<p class=\"entry-text\"><strong>⑧ Marcador do objeto ao qual algo acontece, no qual algo se manifesta ou pelo qual algo é reconhecido: a, por, em relação a.</strong> <span class=\"greek\">ζητεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «requerer alguma coisa no caso de alguém», 1Co 4:2; cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">μάθητε</span>, «para que aprendais em relação a nós», v. 6; cf. Fp 1:30. <span class=\"greek\">ἵνα</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοί</span>, «para que isto seja feito no meu caso», 1Co 9:15 (Justino, D. 77, 3: <span class=\"greek\">τοῦτο</span> <span class=\"greek\">γενόμενον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἡμετέρῳ</span> <span class=\"greek\">Χριστῷ</span>). <span class=\"greek\">ἐδόξαζον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, «talvez glorificavam a Deus no meu caso», Gl 1:24, embora «por minha causa» e «por mim» também sejam possíveis. <span class=\"greek\">μήτι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">ἀνεκεφαλαιώθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἱστορία</span>, GJs 13:1 (ver <span class=\"greek\">ἀνακεφαλαιόω</span> 1). <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «fazer alguma coisa a alguém (ou com alguém)» (Epicteto, Ench. 33, 12; Ps.-Luciano, Philopatr. 18: <span class=\"greek\">μὴ</span> <span class=\"greek\">ἑτεροῖόν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ποιήσῃς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοί</span>; Gn 40:14; Jt 7:24; 1Mc 7:23), Mt 17:12; Lc 23:31. <span class=\"greek\">ἐργάζεσθαί</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, Mc 14:6. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «ter alguma coisa em alguém», Jo 3:15 (mas <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> é frequentemente construído com <span class=\"greek\">πιστεύων</span>; cf. variante textual); cf. 14:30 (ver B. Noack, Satanas u. Soteria, 1948, p. 92). <span class=\"greek\">ἵνα</span> <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">ναὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἰδίῳ</span> <span class=\"greek\">σώματι</span> <span class=\"greek\">ἀναδείξῃ</span>, AcPlCor 2:17 (ver <span class=\"greek\">ἀναδείκνυμι</span> 1).</p><p class=\"entry-text\">Em lugar do dativo comum (Diodoro Sículo 3, 51, 4: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀψύχῳ</span> <span class=\"greek\">ἀδύνατον</span>, «é impossível para uma coisa inanimada»; Élio Aristides 49, 15 K. = 25, p. 492 D.: <span class=\"greek\">ἐν</span> <span class=\"greek\">Νηρίτῳ</span> <span class=\"greek\">θαυμαστὰ</span> <span class=\"greek\">ἐνεδείξατο</span>, «[Deus] mostrou coisas maravilhosas a N.»; 53, p. 629 D.: <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">βελτίστοις</span> <span class=\"greek\">εἰσὶ</span> <span class=\"greek\">παῖδες</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πονηροτάτοις</span> <span class=\"greek\">οὐκέτι</span>, «não é o caso que os muito bons tenham filhos e os muito maus não tenham» [dativos de posse]; 54, p. 653 D.: <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">φαύλοις</span> <span class=\"greek\">θετέον</span>, «para os maus»; EpJer 66: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔθνεσιν</span>; Esopo, Fab. 19, 8 e 348a, 5, variante textual Ch.): <span class=\"greek\">ἀποκαλύψαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοί</span>, Gl 1:16; <span class=\"greek\">φανερόν</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span>, Rm 1:19 (Esopo 15c, 11 Ch.: <span class=\"greek\">τ</span>. <span class=\"greek\">φανερὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span>, «evidente a todos»); <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">βάρβαρος</span> (correspondendo a <span class=\"greek\">τῷ</span> <span class=\"greek\">λαλοῦντι</span> <span class=\"greek\">βάρβ</span>.), 1Co 14:11 (Ânfis, comediógrafo [século IV a.C.], 21: <span class=\"greek\">μάταιός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοί</span>); <span class=\"greek\">δεδομένον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνθρώποις</span>, At 4:12; <span class=\"greek\">θεῷ</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνθρώποις</span>, Lc 2:14. — Especialmente com verbos que indicam choque contra alguma coisa: <span class=\"greek\">προσκόπτω</span>, <span class=\"greek\">πταίω</span>, <span class=\"greek\">σκανδαλίζομαι</span>; ver esses verbetes.</p>\n<p class=\"entry-text\"><strong>⑨ Marcador de causa ou motivo: por causa de, em razão de</strong> (PParis 28, 13 = UPZ 48, 12s. [162/161 a.C.]: <span class=\"greek\">διαλυόμενοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λιμῷ</span>; Sl 30:11; 1Mc 16:3: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐλέει</span>; 2Mc 7:29; Sir 33:17).</p>\n<p class=\"entry-text\">ⓐ Em geral: <span class=\"greek\">ἁγιάζεσθαι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, Hb 10:10; 1Co 7:14; <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπιθυμίαις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">καρδιῶν</span>, Rm 1:24; talvez <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἰσαὰκ</span> <span class=\"greek\">κληθήσεταί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">σπέρμα</span>, Rm 9:7; Hb 11:18 (ambos citam Gn 21:12). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πολυλογίᾳ</span> <span class=\"greek\">αὐτῶν</span>, «por causa de suas muitas palavras», Mt 6:7. <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">πιστεύομεν</span>, «é por essa razão que cremos», Jo 16:30; cf. At 24:16; 1Co 4:4 (Justino, D. 68, 7: <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">δυσωπήσω</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πείθεσθαι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">διδασκάλοις</span> <span class=\"greek\">ὑμῶν</span>, «não vos convencerei também por esse argumento a perder a confiança em vossos mestres?»); talvez 2Co 5:2. Semelhantemente, quanto à ocasião: <span class=\"greek\">ἔφυγεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">τούτῳ</span>, «fugiu por causa dessa declaração», At 7:29; cf. 8:6. Com atração: <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> = <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">ὅτι</span>, «pela razão de que», isto é, «porque», Rm 8:3; Hb 2:18; 6:17.</p>\n<p class=\"entry-text\">ⓑ Com verbos que exprimem sentimento ou emoção, para indicar aquilo a que o sentimento se dirige; assim: <span class=\"greek\">εὐδοκεῖν</span> (<span class=\"greek\">εὐδοκία</span>), <span class=\"greek\">εὐφραίνεσθαι</span>, <span class=\"greek\">καυχᾶσθαι</span>, <span class=\"greek\">χαίρειν</span> e outros.</p>\n<p class=\"entry-text\"><strong>⑩ Marcador de um período de tempo: em, enquanto, quando.</strong></p>\n<p class=\"entry-text\">ⓐ Para indicar um acontecimento ou ação no decorrer do qual, em determinado momento, ocorre alguma coisa: Mt 2:1; <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἡμέραις</span> <span class=\"greek\">ἐκείναις</span>, «naqueles dias», Mt 3:1; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἑξῆς</span>, «depois, em seguida», Lc 7:11; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μεταξύ</span>, «entrementes» (PTebt 72, 190; PFlor 36, 5), Jo 4:31; «no decorrer de, dentro de»: <span class=\"greek\">ἐν</span> <span class=\"greek\">τρισὶν</span> <span class=\"greek\">ἡμέραις</span> (Xenofonte, Ages. 1, 34; Diodoro Sículo 13, 14, 2; 20, 83, 4; Arriano, Anab. 4, 6, 4: <span class=\"greek\">ἐν</span> <span class=\"greek\">τρισὶν</span> <span class=\"greek\">ἡμέραις</span>; Eliano, VH 1, 6; IPriene 9, 29; GDI 1222, 4 [Arcádia]: <span class=\"greek\">ἰν</span> <span class=\"greek\">ἁμέραις</span> <span class=\"greek\">τρισί</span>; EpArist 24; Demétrio, 722 Fgm. 1:3 Jac.), Mt 27:40; Jo 2:19s.</p>\n<p class=\"entry-text\">ⓑ Ponto no tempo em que algo acontece: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">κρίσεως</span>, «no dia do juízo», Mt 11:22 (En 10:6; Justino, D. 38, 2; Taciano 12, 4); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐσχάτῃ</span> <span class=\"greek\">ἡμέρᾳ</span>, «no último dia», Jo 6:44; 11:24; 12:48; cf. 7:37; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐκείνῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὥρᾳ</span>, «naquela hora», Mt 8:13; 10:19; cf. 7:22; Jo 4:53; <span class=\"greek\">ἐν</span> <span class=\"greek\">σαββάτῳ</span>, Mt 12:2; Jo 7:23; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἡμέρᾳ</span>, Jo 11:9 (em oposição a <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">νυκτί</span>, v. 10); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">δευτέρῳ</span>, «na segunda visita», At 7:13; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">παλιγγενεσίᾳ</span>, «na nova era», Mt 19:28. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">παρουσίᾳ</span>, 1Co 15:23; 1Ts 2:19; 3:13; Fp 2:12 (nesta última passagem, em contraste com as demais, não há referência à segunda vinda de Cristo; Justino, D. 31, 1: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐνδόξῳ</span> <span class=\"greek\">γινομένῃ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">παρουσίᾳ</span>; 35, 8; 54, 1 e outros); 1Jo 2:28. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀναστάσει</span>, «na ressurreição», Mt 22:28; Mc 12:23; Lc 14:14; 20:33; Jo 11:24 (Justino, D. 45, 2: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">νεκρῶν</span> <span class=\"greek\">ἀναστάσει</span>); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐσχάτῃ</span> <span class=\"greek\">σάλπιγγι</span>, «ao som da última trombeta», 1Co 15:52; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀποκαλύψει</span>, «na manifestação de Jesus/Cristo (nos últimos dias)», 2Ts 1:7; 1Pe 1:7, 13; 4:13.</p>\n<p class=\"entry-text\">ⓒ Para introduzir uma atividade cujo tempo é indicado: «quando, enquanto, durante» (Diodoro Sículo 23, 12, 1: <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τοιούτοις</span>, «no caso dessa espécie de conduta»); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">προσευχῇ</span>, «quando (vós) orais», Mt 21:22; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">στάσει</span>, «durante a revolta», Mc 15:7; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">διδαχῇ</span>, «no decorrer de seu ensino», Mc 4:2; 12:38. Se Lc 24:35 pertence a esta categoria, o sentido seria «na ocasião de, quando» (mas ver 5b). <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span>, «nisso» (na pregação do evangelho), Ef 6:20; <span class=\"greek\">γρηγοροῦντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> (<span class=\"greek\">τῇ</span> <span class=\"greek\">προσευχῇ</span>), «enquanto estais vigilantes nela (na oração)», Cl 4:2. Especialmente com infinitivo presente substantivado: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σπείρειν</span>, «enquanto (ele) semeava», Mt 13:4; Mc 4:4; cf. 6:48 (ver 7 acima e <span class=\"greek\">βασανίζω</span>); <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">καθεύδειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀνθρώπους</span>, «enquanto as pessoas dormiam», Mt 13:25; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κατηγορεῖσθαι</span> <span class=\"greek\">αὐτόν</span>, «durante as acusações contra ele», Mt 27:12. Com o infinitivo aoristo, o significado é igualmente «quando»; em virtude do sentido fundamental do aoristo, a ação constitui o foco (ver Rob., p. 1073, em oposição a B-D-F §404): <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φωνήν</span>, Lc 9:36; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐπανελθεῖν</span> <span class=\"greek\">αὐτόν</span>, 19:15; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">εἰσελθεῖν</span> <span class=\"greek\">αὐτούς</span>, 9:34. — Com <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span>, «enquanto, durante todo o tempo em que» (Sófocles, Trach. 929; Cleantes [séculos IV/III a.C.], Stoic. I, p. 135, 1 [Diógenes Laércio 7, 171]; Demétrio, 722 Fgm. 1, 11 Jac.; Plutarco, Mor. 356c; Arriano, Anab. 6, 12, 1; Pamprepio de Panópolis [século V d.C.] 1, 22 [ed. H. Gerstinger, SBWienAk 208/3, 1928]), Mc 2:19; Lc 5:34; 24:44 D; Jo 5:7.</p>\n<p class=\"entry-text\"><strong>⑪ Marcador que denota espécie e modo</strong>, especialmente com função auxiliar em perífrases adverbiais (Kühner-G. I, p. 466): <span class=\"greek\">ἐν</span> <span class=\"greek\">δυνάμει</span>, «com poder, poderosamente», Mc 9:1; Rm 1:4; Cl 1:29; 2Ts 1:11; <span class=\"greek\">ἐν</span> <span class=\"greek\">δικαιοσύνῃ</span>, «justamente», At 17:31; Ap 19:11 (cf. Justino, A II, 4, 3; D. 16, 3; 19, 2: <span class=\"greek\">ἐν</span> <span class=\"greek\">δίκῃ</span>); <span class=\"greek\">ἐν</span> <span class=\"greek\">χαρᾷ</span>, «alegremente», Rm 15:32; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐκτενείᾳ</span>, «fervorosamente», At 26:7; <span class=\"greek\">ἐν</span> <span class=\"greek\">σπουδῇ</span>, «zelosamente», Rm 12:8; <span class=\"greek\">ἐν</span> <span class=\"greek\">χάριτι</span>, «graciosamente», Gl 1:6; 2Ts 2:16; <span class=\"greek\">ἐν</span> (<span class=\"greek\">πάσῃ</span>) <span class=\"greek\">παρρησίᾳ</span>, «livremente, abertamente», Jo 7:4; 16:29; Fp 1:20; <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">ἀσφαλείᾳ</span>, At 5:23; <span class=\"greek\">ἐν</span> <span class=\"greek\">τάχει</span> (PHib 47, 35 [256 a.C.]: <span class=\"greek\">ἀπόστειλον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τάχει</span>), Lc 18:8; Rm 16:20; Ap 1:1; 22:6. <span class=\"greek\">ἐν</span> <span class=\"greek\">μυστηρίῳ</span>, 1Co 2:7 (provavelmente ligado não a <span class=\"greek\">σοφία</span>, mas a <span class=\"greek\">λαλοῦμεν</span>: «na forma de um segredo»; cf. Políbio 23, 3, 4; 26, 7, 5; Justino, D. 63, 2: <span class=\"greek\">Μωυσῆς</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολῇ</span> <span class=\"greek\">λέγων</span>; 68, 6: <span class=\"greek\">εἰρήμενον</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">μυστηρίῳ</span>; Diodoro Sículo 17, 8, 5: <span class=\"greek\">ἐν</span> <span class=\"greek\">δωρεαῖς</span> <span class=\"greek\">λαβόντες</span>, «recebendo como presentes»; 2Mc 4:30: <span class=\"greek\">ἐν</span> <span class=\"greek\">δωρεᾷ</span>, «como presente»; Sir 26:3; Políbio 28, 17, 9: <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φερνῇ</span>). Quanto à norma: <span class=\"greek\">ἐν</span> <span class=\"greek\">μέτρῳ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">ἑκάστου</span> <span class=\"greek\">μέρους</span>, «segundo a medida de cada parte individual», Ef 4:16. Sobre 1Co 1:21, ver A. Wedderburn, ZNW 64, 1973, pp. 132–134.</p>\n<p class=\"entry-text\"><strong>⑫ Marcador de especificação ou substância.</strong> Com adjetivo: <span class=\"greek\">πλούσιος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐλέει</span>, «rico em misericórdia», Ef 2:4; cf. Tt 2:3; Tg 1:8. — De substância <strong>que consiste em</strong> (BGU 72, 11 [191 d.C.]: <span class=\"greek\">ἐξέκοψαν</span> <span class=\"greek\">πλεῖστον</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀρούραις</span> <span class=\"greek\">πέντε</span>), <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐντολῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δόγμασιν</span>, Ef 2:15; <span class=\"greek\">ἐν</span> <span class=\"greek\">μηδενὶ</span> <span class=\"greek\">λειπόμενοι</span>, «não carecendo de coisa alguma», Tg 1:4 (em contraste com Justino, A I, 67, 6: <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χρείᾳ</span> <span class=\"greek\">οὖσι</span>); Hb 13:21a. — <strong>Que perfaz, no total</strong> (BGU 970, 14 = Mitt-Wilck. II/2, 242, 14s. [177 d.C.]: <span class=\"greek\">προσηνενκάμην</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">προοῖκα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δραχμαῖς</span> <span class=\"greek\">ἐννακοσίαις</span>), <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">συγγένειαν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ψυχαῖς</span> <span class=\"greek\">ἑβδομήκοντα</span> <span class=\"greek\">πέντε</span>, «toda a parentela, num total de setenta e cinco pessoas», At 7:14. — Muito raramente em lugar do genitivo (Fílon de Bizâncio, Mech. 75, 29: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυλίνδρῳ</span> <span class=\"greek\">κοίλασμα</span>; EpArist 31: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">θεωρία</span> = <span class=\"greek\">ἡ</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">θ</span>.; cf. 29; Taciano 18, 1: <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">εἶδος</span>), <span class=\"greek\">ἡ</span> <span class=\"greek\">δωρεὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χάριτι</span>, «o dom gratuito em beneficência ou graça», Rm 5:15. — DELG; LfgrE, s.v. <span class=\"greek\">ἐν</span>, col. 569 (literatura, especialmente grego antigo); M-M.; TW.</p></section></article>\n<article id=\"entry-enankalizomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐναγκαλίζομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enankalízomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Particípio do primeiro aoristo <span class=\"greek\">ἐναγκαλισάμενος</span>; particípio perfeito <span class=\"greek\">ἐνηγκαλισμένον</span> (TestAbr B 2, p. 105, 10 [Stone, p. 58]); Meleagro (século I a.C.), Anth. Pal. 7, 476, 10; Plutarco, Mor. 492d; Alciphron 4, 19, 5; IG XII/7, 395, 25: <span class=\"greek\">ὧν</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">ἐνηνκαλίσατο</span>; Pv 6:10; 24:33; TestJob 52:10; JosAs 19:3; Mel., P. 24, 164 [B]. <strong>Tomar nos braços, abraçar</strong>; com acusativo <span class=\"greek\">τινά</span>, «alguém», Mc 9:36; 10:16 (Diodoro Sículo 3, 58, 2s.: Cibele toma crianças pequenas nos braços [<span class=\"greek\">ἐναγκ</span>.] e as cura [<span class=\"greek\">σῴζω</span>] quando estão doentes; por isso, é comumente chamada «mãe da montanha» [<span class=\"greek\">ὀρεία</span> <span class=\"greek\">μήτηρ</span>]). — M-M.; DELG, s.v. <span class=\"greek\">ἀγκ</span>-.</p></section></article>\n<article id=\"entry-enalios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνάλιος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enálios⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Píndaro e outros; na forma <span class=\"greek\">εἰνάλιος</span>, já em Homero; também Fílon, Decal. 54. <strong>Pertencente ao mar</strong>; (<span class=\"greek\">τὰ</span>) <span class=\"greek\">ἐνάλια</span>, «criaturas marinhas», Tg 3:7. — DELG, s.v. <span class=\"greek\">ἅλς</span>.</p></section></article>\n<article id=\"entry-enallax-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐναλλάξ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enalláx⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Píndaro e outros; SIG 963, 7; 969, 15; Sb 7350, 4; PGM 4, 145; Gn 48:14; Justino, D. 87, 4. <strong>Na direção oposta, transversalmente, em cruz</strong>. <span class=\"greek\">ὑποδεικνύουσα</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐ</span>., «enquanto lhes indicava a direção errada», 1Cl 12:4. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span>, «colocar as mãos cruzadas», B 13:5 (Gn 48:14). — DELG, s.v. <span class=\"greek\">ἄλλος</span>.</p></section></article>\n<article id=\"entry-enallomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνάλλομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enállomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐναλοῦμαι</span>, Jó 16:4; terceira pessoa do singular do aoristo <span class=\"greek\">ἐνήλατο</span>, LXX. <strong>Mover-se saltando sobre um objeto, saltar sobre</strong> (Ésquilo, Pers. 516; Sófocles, Oed. R. 1261; Jó 6:27 [<span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>]; Mitt-Wilck. I/2, 11, 43 [século II a.C.]), At 19:16, variante do códice D. — DELG, s.v. <span class=\"greek\">ἅλλομαι</span>.</p></section></article>\n<article id=\"entry-enanthropeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνανθρωπέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enanthrōpéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Heliodoro 2, 31, 1: <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">ἐνανθρωπήσασα</span>; Etym. Gud. 467, 2; uso patrístico, ver Lampe, s.v. <strong>Assumir forma humana</strong>, 1Jo 4:17, variante textual. — DELG, s.v. <span class=\"greek\">ἄνθρωπος</span>.</p></section></article>\n<article id=\"entry-enanti-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔναντι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦énanti⟧</span><span class=\"separator\">·</span><span>advérbio e preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Advérbio, funciona como preposição com genitivo (SIG 646, 52 [170 a.C.]: <span class=\"greek\">ἔναντι</span> <span class=\"greek\">Γαί̈</span><span class=\"greek\">ου</span>; POxy 495, 5 [181/189 d.C.]; 2343, 9; frequente na LXX; PsSol 3:4; Justino, D. 77, 2 [aqui por influência de Is 8:4; mas D. 56, 2 (Gn 19:27) e 18 (Gn 18:22) empregam <span class=\"greek\">ἔ</span>. em lugar do <span class=\"greek\">ἐναντίον</span> da LXX]; J. Wackernagel, Hellenistica, 1907, pp. 1ss.).</p><p class=\"entry-text\">① <strong>Relativo à posição à frente de um objeto: defronte, diante de</strong>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «diante de Deus», isto é, no templo (Êx 28:29), Lc 1:8.</p><p class=\"entry-text\">② <strong>Relativo à perspectiva ou percepção de alguém: diante de, figuradamente, aos olhos de, no juízo de</strong>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, At 8:21; 1Cl 39:4 (Jó 4:17, variante textual); <span class=\"greek\">ἔ</span>. <span class=\"greek\">Φαραώ</span>, At 7:10, variante textual. — DELG, s.v. <span class=\"greek\">ἄντα</span> 2.</p></section></article>\n<article id=\"entry-enantion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐναντίον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enantíon⟧</span><span class=\"separator\">·</span><span>advérbio e preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Neutro de <span class=\"greek\">ἐναντίος</span>.</p><p class=\"entry-text\">① <strong>Relativo a estar à frente de: à vista de, diante de</strong>; funciona como preposição com genitivo (Homero e outros; inscrições, papiros, LXX, En; PsSol 8:8; TestSol 22:2 HP; TestJob 15:8; JosAs 23:11; ParJer; ApcMos 32; Josefo, Ant. 16, 344).</p><p class=\"entry-text\">ⓐ <strong>Diante de</strong>: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «diante de Deus», 2Cl 11:7; <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span>, «em público» (Êx 19:11), Lc 20:26; <span class=\"greek\">ἐ</span>. <span class=\"greek\">πάντων</span>, Mc 2:12, variante textual; <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κείραντος</span>, «diante do tosquiador», At 8:32; 1Cl 16:7; B 5:2 (as três referências a Is 53:7). <span class=\"greek\">ἀναγγέλλειν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινός</span>, «proclamar diante de alguém», 1Cl 16:3 (Is 53:2).</p><p class=\"entry-text\">ⓑ <strong>Aos olhos ou no julgamento (de alguém)</strong> (cf. nossa expressão «perante o tribunal»; cf. Gn 10:9; Sir 39:20; 1Mc 3:18; 7:25). <span class=\"greek\">δίκαιος</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, Lc 1:6 (ver <span class=\"greek\">ἐνώπιον</span> 3); <span class=\"greek\">δυνατὸς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, Lc 24:19. <span class=\"greek\">ἔδωκεν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σοφίαν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">Φαραώ</span>, «concedeu-lhe favor e sabedoria perante o faraó», At 7:10 (Gn 39:21).</p><p class=\"entry-text\">② <strong>Advérbio com artigo</strong>: <span class=\"greek\">τοὐναντίον</span>, «por outro lado» (Xenofonte, Platão e outros; 3Mc 3:22; Fílon, Op. M. 2; Josefo, Ant. 1, 270; 18, 24), 2Co 2:7; Gl 2:7; 1Pe 3:9; MPol 12:1. — DELG, s.v. <span class=\"greek\">ἄντα</span>; M-M., s.v. <span class=\"greek\">ἐναντίος</span>.</p></section></article>\n<article id=\"entry-enantioomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐναντιόομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enantióomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Infinitivo aoristo <span class=\"greek\">ἐναντιωθῆναι</span>, 3Mc 3:1; particípio futuro <span class=\"greek\">ἐναντιωθησόμενα</span>, 4Mc 5:26 (ver verbete seguinte; Ésquilo em diante; inscrições, papiros, LXX; EpArist 254; Maneto 609: fragmento 10a, 240 Jac. [em Josefo, C. Ap. 1, 240]; Josefo, Ant. 14, 309; Justino, D. 27, 2). <strong>Estar em oposição a, opor-se (pessoalmente)</strong>, com dativo (Diodoro Sículo 16, 74, 2; inscrições; Sb 8393, 10; UPZ 144, 22 [164 a.C.]; Mitt-Wilck. II/2, 242, 12s. [177 d.C. = BGU 970, 12]: <span class=\"greek\">τοῖς</span> <span class=\"greek\">διατεταγμένοις</span>), At 13:45, variante textual; <span class=\"greek\">τῷ</span> <span class=\"greek\">θελήματι</span> <span class=\"greek\">θεοῦ</span>, «à vontade de Deus», 1Cl 61:1 (cf. PGM 12, 262). — DELG, s.v. <span class=\"greek\">ἄντα</span>.</p></section></article>\n<article id=\"entry-enantios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐναντίος, α, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enantíos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Homero e outros; inscrições, papiros, LXX; PsSol 8:8; Test12Patr; EpArist; Fílon; Josefo; apologistas, exceto Aristides.</p><p class=\"entry-text\">① <strong>Relativo à direção oposta: oposto, contrário, adverso</strong>; do vento (Xenofonte, An. 4, 5, 3; Dio Crisóstomo 17 [34], 19; Josefo, Bell. 3, 421), Mt 14:24; Mc 6:48; At 27:4. <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἐναντίας</span> (grego mais antigo [Heródoto, Tucídides], frequente na LXX; B-D-F §241, 1), <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινός</span>, «defronte de alguém», <span class=\"greek\">παρεστηκέναι</span>, Mc 15:39 (cf. Sir 37:9).</p><p class=\"entry-text\">② <strong>Relativo à oposição: oposto, contrário</strong>; <span class=\"greek\">τινί</span>, «a alguém» (Pv 14:7). <span class=\"greek\">Ἰουδαίων</span> … <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">ἐναντίων</span>, «judeus [...] que se opõem a todas as pessoas», 1Ts 2:15. <span class=\"greek\">ἐναντίον</span> <span class=\"greek\">εἶναί</span> <span class=\"greek\">τινι</span>, «opor-se a alguém»; <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «a Deus», B 16:7; ISm 6:2. <span class=\"greek\">ἐναντίον</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, «fazer algo contrário a alguém» (PSI 282, 13 [183 d.C.]: <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">ἐναντίον</span> <span class=\"greek\">τι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">ὑπογραφῇ</span>; Josefo, Ant. 2, 43; 5, 169; Justino, A II, 4, 3), At 28:17. <span class=\"greek\">ἐναντία</span> <span class=\"greek\">πράσσειν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομά</span> <span class=\"greek\">τινος</span>, «agir contrariamente ao nome de alguém», At 26:9 (<span class=\"greek\">ἐν</span>. <span class=\"greek\">πράσσειν</span>, como em Josefo, Ant. 18, 279; 19, 305). <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτοις</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔργοις</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐναντίοις</span>, «nessas obras [...] e não nas contrárias (más)», 2Cl 4:3 (cf. TestLevi 14:4: <span class=\"greek\">ἐναντίας</span> <span class=\"greek\">ἐντολὰς</span> <span class=\"greek\">διδάσκοντες</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">δικαιώμασιν</span>).</p><p class=\"entry-text\"><span class=\"greek\">τὰ</span> <span class=\"greek\">ἐναντία</span>, «o contrário»; <span class=\"greek\">ἀπολαμβάνειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐναντία</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, «receber o contrário de alguém», Hv 5:7 (cf. POxy 1258, 10s. [45 d.C.]: <span class=\"greek\">εὐορκοῦντι</span> <span class=\"greek\">μέν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">εὖ</span> <span class=\"greek\">εἴη</span>, <span class=\"greek\">ἐπιορκοῦντι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐναντία</span>; igualmente SIG 914, 45; 921, 113; Josefo, C. Ap. 2, 37; Justino, A I, 43, 5ss.; Atenágoras 3, 2). <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἐναντίας</span> (ver 1 acima), «o adversário», Tt 2:8 (cf. Sexto Empírico, Phys. 1, 66: <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἐ</span>.; 2, 69; Eth. 125; Diógenes Laércio 1, 84; Mitt-Wilck. I/2, 461, 1: <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἐναντίας</span>; Fílon, Aet. M. 7). — DELG, s.v. <span class=\"greek\">ἄντα</span>; M-M.; Sv.</p></section></article>\n<article id=\"entry-enarges-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐναργής, ές</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enargḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">De <span class=\"greek\">ἀργής</span>, «brilhante»; desde Homero; inscrições, papiros, EpArist, Fílon; Josefo, Ant. 14, 266, C. Ap. 2, 190; Atenágoras, R. 77, 25; <span class=\"greek\">ἐναργῶς</span>, Justino, D. 54, 1; 114, 1; Atenágoras, R. 65, 1 e outros. <strong>Relativo àquilo que pode ser prontamente percebido: claro, evidente, visível</strong>, Hb 4:12, variante textual (em lugar de <span class=\"greek\">ἐνεργής</span>). Para <span class=\"greek\">ἐνεργής</span> no texto grego de 1Co 16:9 e Fm 6, alguns manuscritos latinos apresentam «evidens» ou «manifesta». — Frisk, s.v. <span class=\"greek\">ἀργής</span>; B. 1233.</p></section></article>\n<article id=\"entry-enaretos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνάρετος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enáretos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong>Relativo a ser excepcional no caráter ou desempenho: de primeira ordem, de alta categoria, excepcional, virtuoso</strong> (termo predileto dos estoicos [ver <span class=\"greek\">ἀρετή</span>; Phryn. 328s. Lob.]; Crisipo, Stoic. III 72; 4Mc 11:5; TestAbr A 20, p. 104, 7 [Stone, p. 56]; Fílon, Deus Imm. 11; Josefo, Bell. 6, 89; OGI 485, 2; 505, 8; papiros; T. Kellis 22, 56 [referente a Deus], 60 [referente aos poderes nos astros celestes]; Justino, A I, 4, 3 e outros; <span class=\"greek\">ἐναρέτως</span>, A I, 21, 6; A II, 9, 1). <strong>Virtuoso</strong>; <span class=\"greek\">βίος</span>, «vida (que satisfaz o mais elevado padrão)», 1Cl 62:1. Possivelmente substantivado: <span class=\"greek\">ἐνάρετον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τέλειον</span> (<span class=\"greek\">τέλειος</span> 1a<span class=\"greek\">α</span>), IPhld 1:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">σημεῖον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐ</span>., «sinal milagroso», AcPl Ha 3, 16 (ver <span class=\"greek\">ἀρετή</span> 2). — DELG, s.v. <span class=\"greek\">ἀρετή</span>.</p></section></article>\n<article id=\"entry-enarmonios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐναρμόνιος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enarmónios⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">De <span class=\"greek\">ἁρμονία</span>, «meio de união», e <span class=\"greek\">ἁρμόζω</span>, «ajustar conjuntamente»; Platão e outros; Fílon. <strong>Harmonioso</strong>: <span class=\"greek\">ἄστρων</span> <span class=\"greek\">ἐναρμόνιον</span> <span class=\"greek\">κίνησιν</span>, «o movimento harmonioso dos astros», Hs 12, 4, 1, variante textual. — DELG, s.v. <span class=\"greek\">ἅρμα</span>.</p></section></article>\n<article id=\"entry-enarchomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνάρχομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enárchomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐνηρξάμην</span>; mais-que-perfeito, terceira pessoa do singular, <span class=\"greek\">ἐνῆρκτο</span>, Nm 17:12 (ver <span class=\"greek\">ἄρχομαι</span>; desde Eurípides, que o emprega como termo técnico sacrificial, construído com acusativo). <strong>Começar</strong> (assim, sem outra conotação, em escritores posteriores: Políbio e outros; PTebt 24, 34; 36 [117 a.C.]; LXX; TestAsh 1:9; EpArist 129); com acusativo <span class=\"greek\">τί</span>, «algo» (em oposição a <span class=\"greek\">ἐπιτελεῖν</span>, <span class=\"greek\">ἐπιτελεῖσθαι</span>), <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">ἀγαθόν</span>, «uma boa obra em vós», Fp 1:6. Uso absoluto (Sb 4369b, 23 [século III a.C.]): <span class=\"greek\">ἐναρξάμενοι</span> <span class=\"greek\">πνεύματι</span>, «vós que começastes (vossa vida cristã) segundo o Espírito» (ou «de modo espiritual»), em oposição a <span class=\"greek\">σαρκί</span>, «segundo a carne», «no modo de existência do velho eu», Gl 3:3 (ver <span class=\"greek\">πνεῦμα</span> 5d<span class=\"greek\">β</span>). — M-M.</p></section></article>\n<article id=\"entry-enatos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνατος, η, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦énatos⟧</span><span class=\"separator\">·</span><span>adjetivo numeral ordinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Homero e outros; sobre a grafia com <span class=\"greek\">ἔνν</span>-, ver B-D-F §11, 2; Rob. 213. <strong>Nono</strong>: <span class=\"greek\">θεμέλιος</span>, «fundamento», Ap 21:20; <span class=\"greek\">ὄρος</span>, «monte», Hs 9, 1, 9; 9, 26, 1. <span class=\"greek\">ὥρα</span>, «hora» (= 15h; TestAbr B 12, p. 117, 2 [Stone, p. 82]), Mt 20:5; 27:45s.; Mc 15:33s.; Lc 23:44; At 10:3, 30; GPt 6:22. Como hora destinada à oração, At 3:1 (ver Elbogen², p. 98; Billerb. II, pp. 696–702 e <span class=\"greek\">προσεύχομαι</span>, final). GJs 2:4 (sinal numeral <span class=\"greek\">Θ̄</span>). — DELG, s.v. <span class=\"greek\">ἐννέα</span>; M-M.; TW.</p></section></article>\n<article id=\"entry-enaphiemi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐναφίημι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enaphíēmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἀφίημι</span>; Heródoto e outros; papiros; Ez 21:22; Josefo, Bell. 6, 336. Sentido primário: «deixar cair dentro». <strong>Deixar, permitir</strong>, Mc 7:12, variante textual (cf. Oribásio, Fgm. 37).</p></section></article>\n<article id=\"entry-eng-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνγ-</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eng-⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <strong><span class=\"greek\">ἐγγ</span>-</strong>.</p></section></article>\n<article id=\"entry-endees-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνδεής, ές</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦endeḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">δέησις</span>, <span class=\"greek\">δέομαι</span>; Sófocles, Heródoto e outros; inscrições, papiros, LXX, Fílon; Josefo, Ant. 17, 175 e outros; Aristides 11, 1; Justino; Taciano 5, 2; Atenágoras, R. 61, 12 e outros.</p><p class=\"entry-text\">① <strong>Relativo à necessidade de bens materiais: pobre, indigente</strong>, At 4:34 (cf. Dt 15:4).</p><p class=\"entry-text\">② <strong>Relativo a ser relativamente deficiente em alguma coisa, como o conhecimento: insuficientemente instruído</strong>, Hv 3, 1, 2. Comparativo <span class=\"greek\">ἐνδεέστερος</span>: <span class=\"greek\">ἐνδεέστερον</span> <span class=\"greek\">γίνεσθαί</span> <span class=\"greek\">τινος</span>, «tornar-se mais necessitado do que alguém», talvez em referência à necessidade do conhecimento da espécie fornecida pelo Pastor, m 8:10; aparentemente com o mesmo tema, <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τινος</span>, 11:8 (conforme indica o contexto, quem possui o Espírito do alto não ostenta conhecimento, mas espera que o Espírito Santo proporcione discernimento e então fala). — DELG, s.v. 2 <span class=\"greek\">δέω</span>; M-M.; TW.</p></section></article>\n<article id=\"entry-endeigma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνδειγμα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éndeigma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">δείγμα</span>, <span class=\"greek\">ἐνδείκνυμι</span>; Platão, Critias 110b; Demóstenes 19, 256. <strong>A prova de alguma coisa, evidência, indicação manifesta</strong>: <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαίας</span> <span class=\"greek\">κρίσεως</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «da justa decisão judicial de Deus», 2Ts 1:5. — DELG, s.v. <span class=\"greek\">δείκνυμι</span>.</p></section></article>"};
